from collections import Counter
import itertools

def task_func(d):
    # Flatten all the lists in the dictionary's values and count occurrences
    counts = Counter(itertools.chain.from_iterable(d.values()))
    return dict(counts)


if __name__ == "__main__":
    example = {"a": [1, 2, 3], "b": [2, 3, 4], "c": [3, 4, 5]}
    print(task_func(example))  # {1: 1, 2: 2, 3: 3, 4: 2, 5: 1}
```

The function chains every list from the dictionary's values into one iterable, counts each integer with `Counter`, and returns the result as a plain dictionary.
